/**
 * Converts an infix expression to postfix (Reverse Polish Notation)
 * using the Shunting Yard algorithm.
 *
 * @param {string} infix - The infix expression (e.g. "3 + 4 * 2")
 * @returns {string} The postfix expression (e.g. "3 4 2 * +")
 */
function priority_queue(infix) {
  const precedence = { '+': 1, '-': 1, '*': 2, '/': 2, '^': 3 };
  const rightAssociative = new Set(['^']);

  const stack = [];
  const output = [];

  const tokens = tokenize(infix);

  for (const token of tokens) {
    if (isNumber(token)) {
      output.push(token);
    } else if (token === '(') {
      stack.push(token);
    } else if (token === ')') {
      while (stack.length && stack[stack.length - 1] !== '(') {
        output.push(stack.pop());
      }
      if (!stack.length) throw new Error('Mismatched parentheses');
      stack.pop(); // remove '('
    } else if (precedence[token] !== undefined) {
      while (
        stack.length &&
        stack[stack.length - 1] !== '(' &&
        precedence[stack[stack.length - 1]] !== undefined &&
        (precedence[stack[stack.length - 1]] > precedence[token] ||
          (precedence[stack[stack.length - 1]] === precedence[token] &&
            !rightAssociative.has(token)))
      ) {
        output.push(stack.pop());
      }
      stack.push(token);
    } else {
      throw new Error(`Unknown token: ${token}`);
    }
  }

  while (stack.length) {
    const op = stack.pop();
    if (op === '(') throw new Error('Mismatched parentheses');
    output.push(op);
  }

  return output.join(' ');
}

/**
 * Tokenizes an infix expression string into an array of tokens.
 * Supports multi-digit integers, decimals, and negative unary minus.
 */
function tokenize(expr) {
  const tokens = [];
  let i = 0;
  while (i < expr.length) {
    if (/\s/.test(expr[i])) {
      i++;
      continue;
    }
    if ('+-*/^()'.includes(expr[i])) {
      // Handle unary minus: if '-' is at start, after '(', or after another operator
      if (
        expr[i] === '-' &&
        (tokens.length === 0 ||
          tokens[tokens.length - 1] === '(' ||
          '+-*/^'.includes(tokens[tokens.length - 1]))
      ) {
        // Read the number following the unary minus
        let num = '-';
        i++;
        while (i < expr.length && /\d/.test(expr[i])) {
          num += expr[i++];
        }
        if (i < expr.length && expr[i] === '.') {
          num += expr[i++];
          while (i < expr.length && /\d/.test(expr[i])) {
            num += expr[i++];
          }
        }
        tokens.push(num);
        continue;
      }
      tokens.push(expr[i++]);
      continue;
    }
    if (/\d/.test(expr[i])) {
      let num = '';
      while (i < expr.length && /\d/.test(expr[i])) {
        num += expr[i++];
      }
      if (i < expr.length && expr[i] === '.') {
        num += expr[i++];
        while (i < expr.length && /\d/.test(expr[i])) {
          num += expr[i++];
        }
      }
      tokens.push(num);
      continue;
    }
    // Support multi-character variable names (alphabetic)
    if (/[a-zA-Z]/.test(expr[i])) {
      let name = '';
      while (i < expr.length && /[a-zA-Z0-9]/.test(expr[i])) {
        name += expr[i++];
      }
      tokens.push(name);
      continue;
    }
    throw new Error(`Unexpected character: ${expr[i]}`);
  }
  return tokens;
}

function isNumber(token) {
  return /^-?\d+(\.\d+)?$/.test(token);
}

// ─── Test Cases ────────────────────────────────────────────────────────

function runTests() {
  const tests = [
    // Basic arithmetic
    { input: '3 + 4', expected: '3 4 +' },
    { input: '3 - 4', expected: '3 4 -' },
    { input: '3 * 4', expected: '3 4 *' },
    { input: '3 / 4', expected: '3 4 /' },

    // Precedence
    { input: '3 + 4 * 2', expected: '3 4 2 * +' },
    { input: '3 * 4 + 2', expected: '3 4 * 2 +' },
    { input: '2 + 3 * 4 - 5', expected: '2 3 4 * + 5 -' },
    { input: '1 + 2 * 3 / 4', expected: '1 2 3 * 4 / +' },

    // Parentheses
    { input: '(3 + 4) * 2', expected: '3 4 + 2 *' },
    { input: '3 * (4 + 2)', expected: '3 4 2 + *' },
    { input: '((3 + 4))', expected: '3 4 +' },
    { input: '(1 + 2) * (3 + 4)', expected: '1 2 + 3 4 + *' },
    { input: '3 * (4 + 2) / (1 - 5)', expected: '3 4 2 + * 1 5 - /' },

    // Right-associative exponentiation
    { input: '2 ^ 3', expected: '2 3 ^' },
    { input: '2 ^ 3 ^ 2', expected: '2 3 2 ^ ^' },
    { input: '2 * 3 ^ 2', expected: '2 3 2 ^ *' },
    { input: '(2 * 3) ^ 2', expected: '2 3 * 2 ^' },

    // Multi-digit and decimal numbers
    { input: '12 + 34', expected: '12 34 +' },
    { input: '3.5 * 2.1', expected: '3.5 2.1 *' },
    { input: '100 / 25', expected: '100 25 /' },

    // Negative / unary minus
    { input: '-3 + 5', expected: '-3 5 +' },
    { input: '(-3 + 5) * 2', expected: '-3 5 + 2 *' },
    { input: '3 * -2', expected: '3 -2 *' },

    // Variables
    { input: 'a + b * c', expected: 'a b c * +' },
    { input: '(x + y) / z', expected: 'x y + z /' },

    // Complex expressions
    { input: '3 + 4 * 2 / (1 - 5) ^ 2 ^ 3', expected: '3 4 2 * 1 5 - 2 3 ^ ^ / +' },
    { input: '((a + b) * (c - d)) / e', expected: 'a b + c d - * e /' },
    { input: 'a ^ b ^ c * d + e', expected: 'a b c ^ ^ d * e +' },

    // Single operand
    { input: '42', expected: '42' },
    { input: 'x', expected: 'x' },

    // Whitespace variations
    { input: '3+4*2', expected: '3 4 2 * +' },
    { input: '  3   +   4  ', expected: '3 4 +' },
  ];

  let passed = 0;
  let failed = 0;

  for (const { input, expected } of tests) {
    const result = priority_queue(input);
    if (result === expected) {
      console.log(`  PASS  "${input}" => "${result}"`);
      passed++;
    } else {
      console.log(`  FAIL  "${input}" => "${result}" (expected "${expected}")`);
      failed++;
    }
  }

  // Error cases
  const errorTests = [
    { input: '(3 + 4', desc: 'unclosed parenthesis' },
    { input: '3 + 4)', desc: 'unmatched closing paren' },
    { input: '3 + @ 4', desc: 'invalid character' },
  ];

  for (const { input, desc } of errorTests) {
    try {
      priority_queue(input);
      console.log(`  FAIL  "${input}" — expected error (${desc})`);
      failed++;
    } catch {
      console.log(`  PASS  "${input}" — correctly threw: ${desc}`);
      passed++;
    }
  }

  console.log(`\n${passed} passed, ${failed} failed out of ${tests.length + errorTests.length} tests`);
  if (failed > 0) process.exit(1);
}

runTests();

